-- SIT-15 Transizione continua 1v0 → 2v1 → 3v2 (insert o aggiornamento)
insert into public.exercises (id, data, updated_at) values ('5eed0000-0000-4000-8000-000000000140', '{"code": "SIT-15", "title": "Transizione continua 1v0 → 2v1 → 3v2", "area": "situazioni", "fase": ["centrale"], "obiettivi": ["transizione", "conduzione", "tiro", "reattività", "velocità", "marcatura", "lettura di gioco", "smarcamento"], "eta": "U9-U13", "giocatori": "2 squadre (Neri 3 file, Rossi 2 file) + portiere", "spazio": "35x20 m (o metà campo in base all’età)", "durata": 15, "materiale": "1 porta + 2 porticine, cinesini per le file, casacche 2 colori, 1 pallone a testa", "perche": "Transizioni continue con superiorità numerica che cresce: chi ha appena attaccato deve subito difendere. Allena reazione, lettura della situazione e velocità di esecuzione in spazi stretti.", "descrizione": "Setup: porta grande con portiere su un lato corto; 2 porticine sul lato opposto. Neri in 3 file dietro le porticine (sinistra, centro, destra), con palla; Rossi in 2 file ai lati della porta grande, il primo della fila destra con palla.\nFase 1 · 1v0: il primo Nero della fila centrale conduce veloce e tira nella porta grande.\nFase 2 · 2v1: subito dopo il tiro partono 2 Rossi (uno con palla) e attaccano le porticine in 2v1; il Nero che ha tirato passa subito da attaccante a difensore.\nFase 3 · 3v2: appena i Rossi tirano o perdono palla, entrano 2 Neri dalle file laterali con un pallone nuovo; con il primo Nero attaccano la porta grande in 3v2 contro i 2 Rossi.\nContro-gol: in qualsiasi fase, chi difende e recupera palla riparte subito e può segnare nelle porte opposte.", "rotazione": "A fine azione ognuno torna in fondo a una fila della propria squadra, cambiando fila a ogni giro. Dopo 5–6′ si invertono i ruoli di Neri e Rossi.", "varianti": "Fase 3 in 3v3 (rientra un terzo Rosso). Tempo massimo per fase (6–8″). Gol in porticina solo dopo un passaggio. Per i più piccoli: 25x15 m e solo fasi 1-2.", "coaching": "Fase 1: conduzione lunga e veloce, tiro senza fermarsi. Fase 2: Rosso con palla attacca il difensore per fissarlo, poi passa al compagno libero; il Nero rientra di corsa e copre la porticina più vicina alla palla. Fase 3: i Neri occupano ampiezza, cercano l’uomo libero, tiro rapido. Sempre: guardarsi intorno prima di ricevere, reazione immediata al cambio di possesso.", "fonte": "Reel labofsoms (Soms Football Lab), “Elite Transition 1v0 to 3v2” — inviato da Andrea, 28/10/2026", "diagram": {"field": {"preset": "spazio", "w": 35, "h": 20}, "steps": [{"title": "Fase 1 · 1v0", "note": "N1 parte dalla fila centrale e conduce veloce verso la porta"}, {"title": "Tiro di N1", "note": "Appena tira, partono i 2 Rossi"}, {"title": "Fase 2 · 2v1", "note": "R1 con palla e R2 attaccano le porticine; N1 rientra e difende"}, {"title": "R1 fissa N1", "note": "R1 conduce sul difensore, R2 si allarga"}, {"title": "Passaggio a R2", "note": "Palla all’uomo libero"}, {"title": "Tiro in porticina", "note": "Appena i Rossi tirano, entrano N2 e N3"}, {"title": "Fase 3 · 3v2", "note": "N2 entra con palla nuova, N3 si allarga, N1 si smarca; i Rossi rientrano a difendere"}, {"title": "Attacco 3v2", "note": "N2 conduce, R2 lo pressa, R1 marca N1"}, {"title": "Passaggio a N1", "note": ""}, {"title": "N1 trova N3 libero", "note": "Palla sul lato debole"}, {"title": "Tiro di N3", "note": "Se i Rossi recuperano palla: contro-gol nelle porticine"}, {"title": "Fine"}], "items": [{"id": "it583", "type": "goal", "pos": {"0": {"x": 34.4, "y": 10}}, "rot": 0}, {"id": "it584", "type": "gk", "pos": {"0": {"x": 33.2, "y": 10}}}, {"id": "it585", "type": "minigoal", "pos": {"0": {"x": 0.6, "y": 6}}, "rot": 180}, {"id": "it586", "type": "minigoal", "pos": {"0": {"x": 0.6, "y": 14}}, "rot": 180}, {"id": "it587", "type": "playerA", "label": "N1", "pos": {"0": {"x": 1.5, "y": 10}, "1": {"x": 24, "y": 11}, "3": {"x": 18, "y": 10}, "4": {"x": 12, "y": 12}, "7": {"x": 15, "y": 10}, "8": {"x": 23, "y": 9}}}, {"id": "it588", "type": "ball", "pos": {"0": {"x": 2.1, "y": 10.4}, "1": {"x": 24.6, "y": 11.4}, "2": {"x": 34.5, "y": 10.5}}}, {"id": "it589", "type": "playerA", "label": "N2", "pos": {"0": {"x": 1.5, "y": 1.5}, "7": {"x": 12, "y": 4}, "8": {"x": 19, "y": 4.5}}}, {"id": "it590", "type": "ball", "pos": {"0": {"x": 2.1, "y": 1.9}, "7": {"x": 12.6, "y": 4.4}, "8": {"x": 19.6, "y": 4.9}, "9": {"x": 23.6, "y": 9.4}, "10": {"x": 24.6, "y": 15.4}, "11": {"x": 34.5, "y": 11}}}, {"id": "it591", "type": "playerA", "label": "N3", "pos": {"0": {"x": 1.5, "y": 18.5}, "7": {"x": 13, "y": 16}, "8": {"x": 24, "y": 15}}}, {"id": "it592", "type": "playerB", "label": "R1", "pos": {"0": {"x": 34, "y": 18.5}, "3": {"x": 22, "y": 14}, "4": {"x": 13, "y": 13.5}, "7": {"x": 20, "y": 12}, "8": {"x": 25.5, "y": 10}}}, {"id": "it593", "type": "ball", "pos": {"0": {"x": 33.4, "y": 18.9}, "3": {"x": 21.4, "y": 14.4}, "4": {"x": 12.4, "y": 13.9}, "5": {"x": 11.4, "y": 5.9}, "6": {"x": 0.8, "y": 6}}}, {"id": "it594", "type": "playerB", "label": "R2", "pos": {"0": {"x": 34, "y": 1.5}, "3": {"x": 22, "y": 5}, "4": {"x": 12, "y": 5.5}, "7": {"x": 20, "y": 7}, "8": {"x": 21, "y": 5.5}}}], "arrows": [{"id": "ar595", "kind": "dribble", "step": 0, "from": {"x": 1.5, "y": 10}, "to": {"x": 24, "y": 11}}, {"id": "ar596", "kind": "shot", "step": 1, "from": {"x": 24.6, "y": 11.4}, "to": {"x": 34.5, "y": 10.5}}, {"id": "ar597", "kind": "dribble", "step": 2, "from": {"x": 34, "y": 18.5}, "to": {"x": 22, "y": 14}, "curve": 1}, {"id": "ar598", "kind": "run", "step": 2, "from": {"x": 34, "y": 1.5}, "to": {"x": 22, "y": 5}, "curve": -1}, {"id": "ar599", "kind": "run", "step": 2, "from": {"x": 24, "y": 11}, "to": {"x": 18, "y": 10}}, {"id": "ar600", "kind": "dribble", "step": 3, "from": {"x": 22, "y": 14}, "to": {"x": 13, "y": 13.5}}, {"id": "ar601", "kind": "run", "step": 3, "from": {"x": 18, "y": 10}, "to": {"x": 12, "y": 12}}, {"id": "ar602", "kind": "run", "step": 3, "from": {"x": 22, "y": 5}, "to": {"x": 12, "y": 5.5}}, {"id": "ar603", "kind": "pass", "step": 4, "from": {"x": 12.4, "y": 13.9}, "to": {"x": 11.4, "y": 5.9}}, {"id": "ar604", "kind": "shot", "step": 5, "from": {"x": 11.4, "y": 5.9}, "to": {"x": 0.8, "y": 6}}, {"id": "ar605", "kind": "dribble", "step": 6, "from": {"x": 1.5, "y": 1.5}, "to": {"x": 12, "y": 4}}, {"id": "ar606", "kind": "run", "step": 6, "from": {"x": 1.5, "y": 18.5}, "to": {"x": 13, "y": 16}}, {"id": "ar607", "kind": "run", "step": 6, "from": {"x": 12, "y": 12}, "to": {"x": 15, "y": 10}}, {"id": "ar608", "kind": "run", "step": 6, "from": {"x": 13, "y": 13.5}, "to": {"x": 20, "y": 12}}, {"id": "ar609", "kind": "run", "step": 6, "from": {"x": 12, "y": 5.5}, "to": {"x": 20, "y": 7}}, {"id": "ar610", "kind": "dribble", "step": 7, "from": {"x": 12, "y": 4}, "to": {"x": 19, "y": 4.5}}, {"id": "ar611", "kind": "run", "step": 7, "from": {"x": 15, "y": 10}, "to": {"x": 23, "y": 9}}, {"id": "ar612", "kind": "run", "step": 7, "from": {"x": 13, "y": 16}, "to": {"x": 24, "y": 15}}, {"id": "ar613", "kind": "run", "step": 7, "from": {"x": 20, "y": 12}, "to": {"x": 25.5, "y": 10}}, {"id": "ar614", "kind": "run", "step": 7, "from": {"x": 20, "y": 7}, "to": {"x": 21, "y": 5.5}}, {"id": "ar615", "kind": "pass", "step": 8, "from": {"x": 19.6, "y": 4.9}, "to": {"x": 23.6, "y": 9.4}}, {"id": "ar616", "kind": "pass", "step": 9, "from": {"x": 23.6, "y": 9.4}, "to": {"x": 24.6, "y": 15.4}}, {"id": "ar617", "kind": "shot", "step": 10, "from": {"x": 24.6, "y": 15.4}, "to": {"x": 34.5, "y": 11}}]}, "id": "5eed0000-0000-4000-8000-000000000140", "updatedAt": "2026-10-01T00:00:00.000Z"}'::jsonb, now()) on conflict (id) do update set data = excluded.data, updated_at = now();
